-- Upload-ready SQL for 5 completed generated posts

-- sql: 1000001001600-layflat
START TRANSACTION;
SET @existing_post=(SELECT ID FROM `ha_posts` WHERE `post_name`='کارچان-مرکزی-looleh-nakhi-tashoo' OR (`post_type`='arak' AND `post_title`='خرید لوله نخی و تاشو در کارچان') LIMIT 1);
SET @post_id=COALESCE(@existing_post,LAST_INSERT_ID());
COMMIT;


